head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = "";
scwin.vMktactCd1 = '';
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "3";
scwin.vRowCount = 0;
scwin.vRowPos = 0;
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vProcsStatCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        btn_Excel.hide();
        lbl_ReturnPos.hide();
        grd_Grid_excel.hide();
        showload.style.display = "none";
        btn_StdCdReq.hide();
        lbl_CondCapSecuTpCd.hide();
        cmb_CondCapSecuTpCd.hide();
        txb_EtcMemo.hide();
        scwin.chgStatComp();

        // 탭지정
        tab_List.setSelectedTabIndex(1);
        tab_Detail.setSelectedTabIndex(1);

        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
        $c.bns.BnsPanelToGroupBox(pnl_IsurCond);
        $c.bns.BnsPanelToGroupBox(pnl_RelInst);
        $c.bns.BnsPanelToGroupBox(pnl_SplitRedmpt);
        $c.bns.BnsPanelToGroupBox(pnl_Strip);

        // 시장조치구분 설정
        scwin.setMktactCd();
        scwin.setDtlTab();
        // 콤보설정
        scwin.setComboCode();
        // 목록조회
        scwin.listSync();

        // 템프데이터셋설정

        // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Temp.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_excel_OnLoadCompleted
 * @description dts_List_excel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_excel_OnLoadCompleted = function(rowcount) {
    try {
        showload.style.display = "none";
        $c.data.downloadGridViewExcel(grd_Grid_excel, {fileName: "일괄상장 월별등록 접수목록", type: "8"});

        // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 복구
        btn_Excel.setDisabled(false);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05300.dts_List_excel_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        scwin.vRowCount = 0;
        scwin.clearIsuInfo();
        scwin.vBndListProcsTpCd = nIndex;
        if (scwin.vBndListProcsTpCd === 2) {
            txb_Dtl.setValue("접수내역");
            btn_Excel.show("");
        } else {
            scwin.vBndListProcsTpCd = '3';
            txb_Dtl.setValue("신청내역");
            btn_Excel.hide();
        }
        scwin.chgStatComp();
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05300.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {
            scwin.vMktactCd1 = dts_List.getCellData(row, 'BND_MKTACT_TP_CD');
            scwin.setDtlTab();
            scwin.vBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
            scwin.vProcsStatCd = dts_List.getCellData(row, "PROCS_STAT_CD");

            // 지방채
            cmb_MunibndTpCd.setDisabled(true);
            if (scwin.vMktactCd1 === '122') {
                cmb_MunibndTpCd.setDisabled(false);
            }

            // 채권유형 국채
            if (scwin.vMktactCd1 === '112') {
                cmb_BndTpCd.setValue('GB');
                cmb_BndTpCd.setDisabled(true);
            }
            // 지방채
            else if (scwin.vMktactCd1 === '122') {
                cmb_BndTpCd.setValue('MB');
                cmb_BndTpCd.setDisabled(true);
            }
            // 특수채
            else if (scwin.vMktactCd1 === '132') {
                cmb_BndTpCd.setValue('AB');
                cmb_BndTpCd.setDisabled(true);
            }
            // 지방공사채
            else if (scwin.vMktactCd1 === '142') {
                cmb_BndTpCd.setValue('CO');
                cmb_BndTpCd.setDisabled(true);
            } else {
                cmb_BndTpCd.setDisabled(false);
            }
            scwin.dtlSync();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05300.dts_List_OnRowPosChanged" });
    }
};

