/**
 * @method
 * @name dts_IsuInfo_OnLoadCompleted
 * @description dts_IsuInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsuInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vRowCount = rowcount;
        // 숨기기
        if (dts_List.getCellData(dts_List.getRowPosition(), 'BND_MKTACT_TP_CD') !== '122') {
            label_47.hide();
            cmb_MunibndTpCd.hide();
        } else {
            label_47.show("");
            cmb_MunibndTpCd.show("");
        }

        // 버튼설정
        scwin.setBtn();
        // 한글금액표기
        if (rowcount > 0 && scwin.vBndListProcsTpCd === 2) {
            txb_AmtHan.setValue($c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));
        }
        if (scwin.vBndListProcsTpCd === 2) return;
        if (rowcount > 0) {
            edt_IsuDd.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ISU_DD"));
            edt_RedmptDd.setValue(dts_List.getCellData(dts_List.getRowPosition(), "REDMPT_DD"));
            edt_IsuAmt.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ISU_AMT"));
            edt_ListAmt.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ISU_AMT"));
            const bkbndTpCd = dts_List.getCellData(dts_List.getRowPosition(), "BKBND_TP_CD");
            // 은행채
            if (bkbndTpCd === '1') {
                edt_FstIntPayDd.setValue(dts_List.getCellData(dts_List.getRowPosition(), "FST_INT_PAY_DD"));
            }
            // 은행채추가
            else if (bkbndTpCd === '3') {
                txb_EtcMemo.setValue('[상환기간(년) : ' + dts_List.getCellData(dts_List.getRowPosition(), "PACK_LIST_APPL_MM") + ']');
                edt_FstIntPayDd.setValue(dts_List.getCellData(dts_List.getRowPosition(), "FST_INT_PAY_DD"));
                edt_CoupnRt.setValue(dts_List.getCellData(dts_List.getRowPosition(), "COUPN_RT"));
                edt_IntPayCalcMms.setValue(dts_List.getCellData(dts_List.getRowPosition(), "INT_PAY_CALC_MMS"));
                edt_IntPayUnitMms.setValue(dts_List.getCellData(dts_List.getRowPosition(), "INT_PAY_UNIT_MMS"));
            } else {
                txb_EtcMemo.setValue('[발행월 : ' + dts_List.getCellData(dts_List.getRowPosition(), "PACK_LIST_APPL_MM") + ']');
            }

            // 물가연동채구분
            if (dts_IsuInfo.getCellData(1, 'ISUR_CD') === 'GB035') {
                cmb_InfllnkYn.setDisabled(false);
                edt_IsuDdRefIdx.setDisabled(false);
            } else {
                cmb_InfllnkYn.setDisabled(true);
                edt_IsuDdRefIdx.setDisabled(true);
            }
        }
        txb_AmtHan.setValue($c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));

        // 금액여분적용
        scwin.setMargin();

        // 신용등급 SF
        if (scwin.vBndListProcsTpCd !== '1' &&
            cmb_AsstSecutizTpCd.getValue() === '') {
            cmb_SfValuYn1.setValue('');
            cmb_SfValuYn2.setValue('');
            cmb_SfValuYn3.setValue('');
            cmb_SfValuYn4.setValue('');
            cmb_SfValuYn1.setDisabled(true);
            cmb_SfValuYn2.setDisabled(true);
            cmb_SfValuYn3.setDisabled(true);
            cmb_SfValuYn4.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05300.dts_IsuInfo_OnLoadCompleted" });
    }
};

