/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
        }
        if (scwin.processGp === '9') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "표준코드요청"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05300.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
            scwin.listSync();
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
            scwin.listSync();
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
            scwin.listSync();
        }
        if (scwin.processGp === '9') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "표준코드요청"));
        }
        if (scwin.processGp === '1') {
            scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05300.trs_Save_OnSuccess" });
    }
};

