        if (rowcount >= 1) {
            scwin.setUdwrtInst(1, cmb_BndUdwrtInstCd1, edt_UdwrtAmt1);
        }
        if (rowcount >= 2) {
            scwin.setUdwrtInst(2, cmb_BndUdwrtInstCd2, edt_UdwrtAmt2);
