        if (rowcount >= 3) {
            scwin.setUdwrtInst(3, cmb_BndUdwrtInstCd3, edt_UdwrtAmt3);
        }
        if (rowcount >= 4) {
            scwin.setUdwrtInst(4, cmb_BndUdwrtInstCd4, edt_UdwrtAmt4);
        }
        if (rowcount >= 5) {
            edt_UdwrtAmt5.setValue(dts_UdwrtInst.getCellData(5, 'UDWRT_AMT'));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05300.dts_UdwrtInst_OnLoadCompleted" });
