///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 신청/접수 목록을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    $c.cm.setColumnProp(grd_AcptList, "CHK", "headcheck", false);
    let param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; // 시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; // 채권처리구분(1:신청,2:접수)

    let dsNm = 'BNS_APPL_ACPT_LIST';
    let qryId = 'lds.stf.bnspack.select.listApplBymm';
    if (scwin.vBndListProcsTpCd === '2') {
        qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    }
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd === '1') {
    } else {
    }
};

/**
 * @method
 * @name setMktactCd
 * @description 신규상장 채권시장조치구분코드를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setMktactCd = function() {
    scwin.vMktactCd = "112122132";
};

/**
 * @method
 * @name dtlSync
 * @description 그리드 선택 시 상세내역을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.dtlSync = function() {
    let param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; // 채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; // 채권처리구분(1:신청,2:접수)

    // 종목정보
    let dsNm = 'BNS_ISU_INFO';
    let qryId = 'lds.stf.bnscommon.select.readIsuInfo';
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_IsuInfo, dsNm, qryId, param);

    // 신용평가정보
    let dsNm = 'BNS_CREDIT_INFO';
    let qryId = 'lds.stf.bnscommon.select.listCredit';
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_Credit, dsNm, qryId, param);

    // 인수기관정보
    let dsNm = 'BNS_UDWRT_INST';
    let qryId = 'lds.stf.bnscommon.select.listUdwrtInst';
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_UdwrtInst, dsNm, qryId, param);

    // 분할상환
    let dsNm = 'BNS_SPLIT_REDMPT';
    let qryId = 'lds.stf.bnscommon.select.listSplitRedmpt';
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_SplitRedmpt, dsNm, qryId, param);
};

