/**
 * @method
 * @name minusGumriOK
 * @description 개별 체크한다. (JACKAL_191129)
 * @param {Object} obj 컴포넌트
 * @param {String} msg 항목명
 * @returns {void}
 * @hidden N
 */
scwin.minusGumriOK = function(obj, msg) {
    const obj_rt = obj.getValue();
    if (obj_rt < 0) {
        if (!window.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            // setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};

/**
 * @method
 * @name minusGumriCheck
 * @description 개별 체크한다. (JACKAL_191129 / edt_CoupnRt COUPN_RT / edt_ScbdInt SCBD_INT / edt_BkHoldyDdPrincAcrintRt BK_HOLDY_DD_PRINC_ACRINT_RT / edt_BkHoldyDdIntCmpAcrintRt   BK_HOLDY_DD_INT_CMP_ACRINT_RT / edt_GrtYd GRT_YD / edt_AddYd ADD_YD)
 * @returns {void}
 * @hidden N
 */
scwin.minusGumriCheck = function() {
    if (!scwin.minusGumriOK(edt_CoupnRt, '표면이자율') &&
        !scwin.minusGumriOK(edt_ScbdInt, '낙찰금리') &&
        !scwin.minusGumriOK(edt_BkHoldyDdPrincAcrintRt, '휴무(원금)경과금리') &&
        !scwin.minusGumriOK(edt_BkHoldyDdIntCmpAcrintRt, '휴무(이자)경과금리') &&
        !scwin.minusGumriOK(edt_GrtYd, '보장수익률') &&
        !scwin.minusGumriOK(edt_AddYd, '추가수익률')) return 1;

    else return 0;
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function() {
    // 마이너스 금리 체크 (처리완료 및 수정만 체크토록 수정)
    if (!scwin.minusGumriCheck()) return 1; // JACKAL_191129

    // 종목정보체크
    if ($c.bns.fn_CheckNewListIsuInfo(dts_IsuInfo) > 0) return;
    if (await scwin.checkEach() > 0) return;
    if (scwin.processGp === '4') {
        if ($c.bns.fn_CheckModAndRet("ULDBNS05300.xml", dts_CheckCmData, scwin.vBndApplId) > 0) return;
    }
    // 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if ($c.bns.fn_ChkBndClssAndIsur("ULDBNS05300.xml", dts_IsuInfo, scwin.vMktactCd) > 0) return;

    // 고객요건에의한 체크 추가. 2024-06-05 by김효준
    if ($c.bns.fn_AddCheck() > 0) return;

    // 특수채체크
    if (cmb_BndTpCd.getValue() === 'AB') {
        if (dts_IsuInfo.getCellData(1, 'SPECLBND_ISUR_CD') === '') {
            await $c.win.alert('특수채 발행기관 코드가 없습니다.');
            return;
        }
    } else {
        dts_IsuInfo.setCellData(1, 'SPECLBND_ISUR_CD', '');
    }

    // 소액채권 표준코드와 상장시 표면이자율이 상이한지 체크 JACKAL_20.01.31
    const qryId111 = 'lds.stf.bnsnew.select.smallbndyn.coupnrt.stdcd';
    const dsNm111 = 'BNS_ISU_INFO';
    const param111 = '&{P}V_STD_CD=' + txb_StdCd.getValue();
    dts_CheckCmData.SyncLoad = true;
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_CheckCmData, dsNm111, qryId111, param111);
    if (dts_CheckCmData.getRowCount() > 0) {
        const cnt = dts_CheckCmData.getCellData(1, 'COUPN_RT');
        if (cnt !== dts_IsuInfo.getCellData(1, "COUPN_RT")) {
            await $c.win.alert("표면이자율이 표준코드부여 시와 다름니다.\n" + "관련 담당자에게 반드시 연락바랍니다.\n" + "연락 부재시 신고시장수익률 장애가 발생합니다.\n" + "[연락처]\n" + "KRX IT관리부 정보시스템팀 백윤경 과장(9875)\n" + "KRX IT관리부 증권시스템팀 김승한(9193)\n" + "코스콤 시장업무부 채권RDS 이승규 차장(676-8215)\n" + "코스콤 Check 송기성 과장(767-8621)");
            // return 0;

        }
    }

    // 수수료체크
    // if(fn_CheckFee(vScrenID, '1', dts_CheckCmData, vBndApplId) > 0) return;
    // 처리완료,수정
    let hasAttachDoc = dts_IsuInfo.getCellData(1, "HAS_ATTACH_DOC");
    if (scwin.processGp === '4') {
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '수정')) return;
    } else {
        // 적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmData1("ULDBNS05300.xml", dts_CheckCmData, edt_ListDd.getValue(), scwin.vBndApplId) > 0) return;
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '처리완료')) return;
    }

    // 발행방법설정
    const ISU_METHD_INDIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_INDIRECT');
    const ISU_METHD_DIRECT = dts_IsuInfo.getCellData(1, 'ISU_METHD_DIRECT');
    const ISU_METHD_PPBOND = dts_IsuInfo.getCellData(1, 'ISU_METHD_PPBOND');
    dts_IsuInfo.setCellData(1, 'BND_ISU_METHD_CD', ISU_METHD_INDIRECT + '' + ISU_METHD_DIRECT + '' + ISU_METHD_PPBOND);

    // 탭 데이터셋 설정
    scwin.setCreditData();
    scwin.setUdwrtInstData();

    // 변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    dts_SplitRedmpt.UseChangeInfo = "False";
    let url = "/bns/PackList.do?method=processAcptProcessComplt";
    if (scwin.processGp === '4') {
        url = "/bns/PackList.do?method=updateAcpt";
    }
    url += "&SCREN_ID=" + "ULDBNS05300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += ", STRT_DD=" + dts_IsuInfo.getCellData(1, "LIST_DD");
    let dsKeyValue = "JSP(";
    dsKeyValue += "I:pInput=dts_IsuInfo";
    dsKeyValue += ", I:pInput1=dts_Credit";
    dsKeyValue += ", I:pInput2=dts_UdwrtInst";
    dsKeyValue += ", I:pInput8=dts_SplitRedmpt";
    dsKeyValue += ")";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = dsKeyValue;
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name checkEach
 * @description 개별정보를 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkEach = async function() {
    // 처리완료 시 체크
    if (scwin.processGp === '3') {
        // 표면이자율 체크
        if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") === '') {
            await $c.win.alert("표면이자율 확정여부를 선택하십시오.");
            return 1;
        } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") === 'Y' &&
            dts_IsuInfo.getCellData(1, "COUPN_RT") === '') {
            await $c.win.alert("표면이자율 확정시에는 표면이자율을 입력하십시오.");
            return 1;
        } else if (dts_IsuInfo.getCellData(1, "COUPN_RT_FINAL_YN") === 'N' &&
            dts_IsuInfo.getCellData(1, "COUPN_RT") !== '') {
            if (!window.confirm('표면이자율이 미확정입니다.그래도 처리하시겠습니까?')) return 1;
        }
    }
    if (scwin.vBndListProcsTpCd === '2') {
        // 신용기관체크
        const creditMsg = '신용평가기관을 선택하지 않으셨습니다.';
        const creditMsg1 = '신용등급을 선택하지 않으셨습니다.';
        if (cmb_CreditValuInstCd1.getValue() === '' &&
            cmb_ByinstCreditValuGrd1.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd1.focus();
            return 1;
        } else if (cmb_CreditValuInstCd1.getValue() !== '' &&
            cmb_ByinstCreditValuGrd1.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd1.focus();
            return 1;
        }
        if (cmb_CreditValuInstCd2.getValue() === '' &&
            cmb_ByinstCreditValuGrd2.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd2.focus();
            return 1;
        } else if (cmb_CreditValuInstCd2.getValue() !== '' &&
            cmb_ByinstCreditValuGrd2.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd2.focus();
            return 1;
        }
        if (cmb_CreditValuInstCd3.getValue() === '' &&
            cmb_ByinstCreditValuGrd3.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd3.focus();
            return 1;
        } else if (cmb_CreditValuInstCd3.getValue() !== '' &&
            cmb_ByinstCreditValuGrd3.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd3.focus();
            return 1;
        }
        if (cmb_CreditValuInstCd4.getValue() === '' &&
            cmb_ByinstCreditValuGrd4.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd4.focus();
            return 1;
        } else if (cmb_CreditValuInstCd4.getValue() !== '' &&
            cmb_ByinstCreditValuGrd4.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd4.focus();
            return 1;
        }

        // 발행용도 총계 체크
        let listAmt = edt_ListAmt.getValue();
        if (edt_EqmtFnd.getValue() !== '' ||
            edt_RefundFnd.getValue() !== '' ||
            edt_OperFnd.getValue() !== '' ||
            edt_MiscFnd.getValue() !== '') {
            let eqmtAmt = edt_EqmtFnd.getValue();
            if (eqmtAmt === '') eqmtAmt = 0;
            let refundAmt = edt_RefundFnd.getValue();
            if (refundAmt === '') refundAmt = 0;
            let operAmt = edt_OperFnd.getValue();
            if (operAmt === '') operAmt = 0;
            let miscAmt = edt_MiscFnd.getValue();
            if (miscAmt === '') miscAmt = 0;
            const fndAmt = parseInt(eqmtAmt) + parseInt(refundAmt) + parseInt(operAmt) + parseInt(miscAmt);
            if (listAmt !== fndAmt) {
                await $c.win.alert('발행용도 금액 총계를 확인하십시오.');
                tab_Detail.setSelectedTabIndex(1);
                if (edt_EqmtFnd.getValue() !== '') {
                    edt_EqmtFnd.focus();
                    return 1;
                } else if (edt_RefundFnd.getValue() !== '') {
                    edt_RefundFnd.focus();
                    return 1;
                } else if (edt_OperFnd.getValue() !== '') {
                    edt_OperFnd.focus();
                    return 1;
                } else if (edt_MiscFnd.getValue() !== '') {
                    edt_MiscFnd.focus();
                    return 1;
                }
            }
        }

        // 인수기관체크
        let isHas = false;
        const udwrAmtMsg = '인수기관 금액을 입력하십시오.';
        const udwrInstMsg = '인수기관을 선택 하십시오.';
        const udwrt1 = cmb_BndUdwrtInstCd1.getValue();
        const udwrt2 = cmb_BndUdwrtInstCd2.getValue();
        const udwrt3 = cmb_BndUdwrtInstCd3.getValue();
        const udwrt4 = cmb_BndUdwrtInstCd4.getValue();
        let udwrt1Amt = 0;
        let udwrt2Amt = 0;
        let udwrt3Amt = 0;
        let udwrt4Amt = 0;
        let udwrt5Amt = 0;
        if (udwrt1 !== '') {
            udwrt1Amt = edt_UdwrtAmt1.getValue();
            if (udwrt2 === udwrt1) {
                isHas = true;
            } else if (udwrt3 === udwrt1) {
                isHas = true;
            } else if (udwrt4 === udwrt1) {
                isHas = true;
            }
            if (edt_UdwrtAmt1.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt1.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt1.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd1.focus();
                return 1;
            }
        }
        if (udwrt2 !== '') {
            udwrt2Amt = edt_UdwrtAmt2.getValue();
            if (udwrt1 === udwrt2) {
                isHas = true;
            } else if (udwrt3 === udwrt2) {
                isHas = true;
            } else if (udwrt4 === udwrt2) {
                isHas = true;
            }
            if (edt_UdwrtAmt2.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt2.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt2.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd2.focus();
                return 1;
            }
        }
        if (udwrt3 !== '') {
            udwrt3Amt = edt_UdwrtAmt3.getValue();
            if (udwrt1 === udwrt3) {
                isHas = true;
            } else if (udwrt2 === udwrt3) {
                isHas = true;
            } else if (udwrt4 === udwrt3) {
                isHas = true;
            }
            if (edt_UdwrtAmt3.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt3.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt3.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd3.focus();
                return 1;
            }
        }
        if (udwrt4 !== '') {
            udwrt4Amt = edt_UdwrtAmt4.getValue();
            if (udwrt1 === udwrt4) {
                isHas = true;
            } else if (udwrt2 === udwrt4) {
                isHas = true;
            } else if (udwrt3 === udwrt4) {
                isHas = true;
            }
            if (edt_UdwrtAmt4.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt4.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt4.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd4.focus();
                return 1;
            }
        }
        if (isHas) {
            await $c.win.alert('동일한 인수기관을 선택 하셨습니다. 인수기관을 확인하여 주십시요.');
            return 1;
        }

        // 인수금액 총계 체크
        udwrt5Amt = edt_UdwrtAmt5.getValue();
        if (udwrt5Amt === '') udwrt5Amt = 0;
        const udwrtAmt = parseInt(udwrt1Amt) + parseInt(udwrt2Amt) + parseInt(udwrt3Amt) + parseInt(udwrt4Amt) + parseInt(udwrt5Amt);
        if (udwrtAmt > 0) {
            if (listAmt !== udwrtAmt) {
                await $c.win.alert('인수금액 총계를 확인하십시오.');
                tab_Detail.setSelectedTabIndex(2);
                if (edt_UdwrtAmt1.getValue() !== '') {
                    edt_UdwrtAmt1.focus();
                    return 1;
                } else if (edt_UdwrtAmt2.getValue() !== '') {
                    edt_UdwrtAmt2.focus();
                    return 1;
                } else if (edt_UdwrtAmt3.getValue() !== '') {
                    edt_UdwrtAmt3.focus();
                    return 1;
                } else if (edt_UdwrtAmt4.getValue() !== '') {
                    edt_UdwrtAmt4.focus();
                    return 1;
                } else if (edt_UdwrtAmt5.getValue() !== '') {
                    edt_UdwrtAmt5.focus();
                    return 1;
                }
            }
        }
        if (!$c.stf.checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
        if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;

        // 분할상환체크
        const rowCnt = dts_SplitRedmpt.getRowCount();
        for (let idx = 1; idx <= rowCnt; idx++) {
            if (dts_SplitRedmpt.getCellData(idx, 'INT_PAY_DD').length !== 8) {
                await $c.win.alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
                dts_SplitRedmpt.setRowPosition(idx, 0);
                return 1;
            }
        }

        // 환율적용 발행금액,상장금액 체크
        if (cmb_CurrTpCd.getValue() !== '' &&
            cmb_CurrTpCd.getValue() !== '1') {
            let isuAmt = edt_IsuAmt.getValue();
            let listAmt = edt_ListAmt.getValue();
            if (isuAmt === '') isuAmt = 0;
            if (listAmt === '') listAmt = 0;
            const exchrt = $c.bns.fn_SearchExchrt("ULDBNS05300.xml", dts_CheckExa, cmb_CurrTpCd.getValue(), '1');
            isuAmt = isuAmt * exchrt;
            listAmt = listAmt * exchrt;

            // 메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
            if (parseInt(isuAmt) < parseInt(listAmt)) {
                await $c.win.alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
                return 1;
            }
            if (isuAmt <= 100000000) {
                await $c.win.alert("발행금액이 1억원 이하입니다.");
            } else if (isuAmt >= 1000000000000) {
                await $c.win.alert("발행금액이 1조원 이상입니다.");
            }
            if (listAmt <= 100000000) {
                await $c.win.alert("상장금액이 1억원 이하입니다.");
            } else if (listAmt >= 1000000000000) {
                await $c.win.alert("상장금액이 1조원 이상입니다.");
            }
        }
    }
    return 0;
};

/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.acpt = function() {
    // 종목정보체크
    if ($c.bns.fn_CheckNewListIsuInfo(dts_IsuInfo) > 0) return;
    // 적용일,매매일,마감일,채권마감 체크
    if ($c.bns.fn_CheckCmData1("ULDBNS05300.xml", dts_CheckCmData, edt_ListDd.getValue(), scwin.vBndApplId) > 0) return;
    // 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if ($c.bns.fn_ChkBndClssAndIsur1("ULDBNS05300.xml", dts_IsuInfo, scwin.vMktactCd) > 0) return;

    // 고객요건에의한 체크 추가. 2024-06-05 by김효준
    if ($c.bns.fn_AddCheck() > 0) return;

    // 접수
    let hasAttachDoc = dts_IsuInfo.getCellData(1, "HAS_ATTACH_DOC");
    if (!$c.bns.fn_EndConfirm(hasAttachDoc, '접수')) return;
    let url = "/bns/PackList.do?method=processAcptBymm";
    url += "&SCREN_ID=" + "ULDBNS05300.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let param = "BND_APPL_ID=" + scwin.vBndApplId;
    param += ", BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += ", STRT_DD=" + dts_IsuInfo.getCellData(1, "LIST_DD");
    param += ", PACK_LIST_APPL_MM=" + dts_List.getCellData(dts_List.getRowPosition(), "PACK_LIST_APPL_MM");
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

