/**
 * @method
 * @name getParInst
 * @description 기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParInst = function(arrPar) {
    let initTpCd = '0';
    // 관련기관-대표주관회사
    if (vSelObj.id === 'cmb_BndMajagntComCd') {
        initTpCd = '1';
    }
    // 관련기관-보증기관
    else if (vSelObj.id === 'cmb_GrtInstCd') {
        initTpCd = '2';
    }
    // 관련기관-등록기관
    else if (vSelObj.id === 'cmb_RegInstCd') {
        initTpCd = '3';
    }
    // 관련기관-원리금지급대행
    else if (vSelObj.id === 'cmb_PrincintPayAgntCd') {
        initTpCd = '4';
    }
    // 관련기관-수탁기관
    else if (vSelObj.id === 'cmb_TrstInstCd') {
        initTpCd = '5';
    }
    arrPar[0] = {
        INST_CD: vSelObj.getValue(),
        INST_NM: vSelObj.getValue(),
        LBL_NM: '',
        INIT_TP_CD: initTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

