/**
 * @method
 * @name chkInstAlert
 * @description 발행기관 상태가 정상인지 확인한다.
 * @param {*} selObj selObj
 * @returns {void}
 * @hidden N
 */
scwin.chkInstAlert = function(selObj) {
    if (selObj.getValue() === '') return;
    if ($c.bns.fn_ShowInstAlert(dts_InstCd, $c.cp.getNameValueRow(dts_InstCd, "INST_CD", selObj.getValue())) > 0) {
        selObj.setValue('');
    }
};

/**
 * @method
 * @name setCheckBoxALL
 * @description 그리드 체크박스 전체선택 또는 전체선택 해제
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        // if (dtsObj.NameString(i, "PROCS_STAT") != '처리완료') { //처리완료만 팀장확인 대상임
        if (dtsObj.getCellData(i, "PROCS_STAT") !== '처리완료' || (dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== "undefined" && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== '-' && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== '')) {
            // 처리완료만 팀장확인 대상임
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};

/**
 * @method
 * @name setCheckBox
 * @description 그리드 선택된 row 체크박스 선택 또는 선택해제
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBox = function(grdObj, dtsObj, row) {
    // var vcd = "";
    // if (bCheck == '1')    { vcd  = "T"; }
    // else                        { vcd  = "F"; }

    grdObj.setBroadcast(false);
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        // if (i == row) {//해당row 체크
        //    dtsObj.NameString(i, "CHK") = "T";
        // } else {
        dtsObj.setCellData(i, "CHK", "F");
        // }

    }
    dtsObj.setCellData(row, "CHK", "T");
    grdObj.setBroadcast(true);
};

/**
 * @method
 * @name setTransData
 * @description 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 * @returns {void}
 * @hidden N
 */
scwin.setTransData = function() {
    let nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excelDownload = function() {
    if (scwin.vRowCount === 0) return;
    showload.style.display = "";

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리
    btn_Excel.setDisabled(true);
    btn_Excel.setBackgroundImage("../img/btn_excelsave_d.gif");
    let param = '';
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd; // 시장조치코드
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; // 채권처리구분(1:신청,2:접수)

    // var qryId = 'lds.stf.bnspack.select.listApplBymm.excel';
    let qryId = '';
    if (scwin.vBndListProcsTpCd === '2') {
        qryId = 'lds.stf.bnscommon.select.listApplAndAcpt.excel';
    }
    let dsNm = 'BNS_APPL_ACPT_LIST_EXCEL';
    $c.bns.fn_SearchBns("ULDBNS05300.xml", dts_List_excel, dsNm, qryId, param);
};
